import React from "react";

/* 0.7 — Training vs inference. Static, because there is nothing to fiddle
   with: the point is simply which box is frozen. */

export default function TrainVsInfer() {
  return (
    <div className="viz">
      <div className="tvi">
        <div className="tvi-col">
          <h4>Training — months, once</h4>
          <ul>
            <li>Weights change</li>
            <li>Thousands of GPUs</li>
            <li>Pretraining, then post-training (SFT, RLHF)</li>
            <li>Ends. The result is a frozen file.</li>
          </ul>
        </div>
        <div className="tvi-arrow" aria-hidden="true">
          →
        </div>
        <div className="tvi-col frozen">
          <h4>Inference — milliseconds, constantly</h4>
          <ul>
            <li>
              Weights are <strong>frozen</strong>
            </li>
            <li>Your prompt goes in, tokens come out</li>
            <li>Nothing you say is learned</li>
            <li>Every "memory" is you re-sending text</li>
          </ul>
        </div>
      </div>

      <p className="viz-note">
        This is why "the model will learn from our users" is usually wrong, and
        why fine-tuning is the answer far less often than people reach for it.
        Fine-tuning changes <em>style, format and behaviour</em>. It does not
        reliably add facts, it will not keep them current, and it cannot cite a
        source. If the problem is "the model doesn't know our data", the answer
        is Track 2, not a training run.
      </p>
    </div>
  );
}
