import React from "react";

/* ============================================================
   🖼  PROJECT PREVIEWS — a picture of each build
   ------------------------------------------------------------
   One small SVG per project in learnGuide.js `projects`, keyed
   by id. They sketch the thing you end up with (a token bar, a
   JSON reply, a loop, a graph), so the gallery can show rather
   than describe. Colours come from CSS variables on .pv:
   --pv-a (accent), --pv-ink, --pv-dim, --pv-line. Motion lives
   in ProjectLadder.css and only runs on .is-live (hovered or
   featured), and never under reduced motion.
   ============================================================ */

const W = 320;
const H = 200;

function Frame({ label, children }) {
  return (
    <svg
      className="pv"
      viewBox={`0 0 ${W} ${H}`}
      role="img"
      aria-label={label}
      preserveAspectRatio="xMidYMid meet"
    >
      {children}
    </svg>
  );
}

/* 01 — tokens and cost */
function CostLens() {
  const toks = [34, 22, 48, 18, 30, 40, 16, 28, 36, 20, 44];
  let x = 28;
  return (
    <Frame label="A sentence split into tokens, with its cost and context use">
      {toks.map((w, i) => {
        const r = (
          <rect
            key={i}
            className="pv-tok"
            style={{ animationDelay: `${i * 70}ms` }}
            x={x}
            y={60 + (i > 5 ? 34 : 0)}
            width={w}
            height={22}
            rx={5}
            fill="var(--pv-a)"
            opacity={i % 2 ? 0.28 : 0.55}
          />
        );
        x = i === 5 ? 28 : x + w + 5;
        return r;
      })}
      <text x={28} y={152} className="pv-num">
        $0.0042
      </text>
      <text x={292} y={152} textAnchor="end" className="pv-cap">
        per call · 312 tokens
      </text>
      <rect
        x={28}
        y={166}
        width={264}
        height={6}
        rx={3}
        fill="var(--pv-line)"
      />
      <rect
        className="pv-grow"
        x={28}
        y={166}
        width={58}
        height={6}
        rx={3}
        fill="var(--pv-a)"
      />
    </Frame>
  );
}

