/* 05 — a graph with a loop edge */
function PatternsKit() {
  const node = (x, y, t, on) => (
    <g>
      <rect
        x={x - 38}
        y={y - 15}
        width={76}
        height={30}
        rx={8}
        fill="var(--pv-bg)"
        stroke={on ? "var(--pv-a)" : "var(--pv-dim)"}
      />
      <text x={x} y={y + 5} textAnchor="middle" className="pv-cap pv-ink">
        {t}
      </text>
    </g>
  );
  return (
    <Frame label="A workflow graph with an evaluator loop back to the generator">
      <path d="M72 100 H112" stroke="var(--pv-dim)" strokeWidth={1.5} />
      <path d="M188 100 H222" stroke="var(--pv-dim)" strokeWidth={1.5} />
      <path
        className="pv-dash"
        d="M260 84 C260 30, 150 30, 150 84"
        fill="none"
        stroke="var(--pv-a)"
        strokeWidth={2}
        strokeDasharray="5 5"
      />
      <path
        d="M144 76 L150 86 L156 76"
        fill="none"
        stroke="var(--pv-a)"
        strokeWidth={2}
      />
      {node(40, 100, "start", false)}
      {node(150, 100, "generate", true)}
      {node(260, 100, "evaluate", true)}
      <path d="M260 116 V146" stroke="var(--pv-dim)" strokeWidth={1.5} />
      {node(260, 160, "done", false)}
      <text x={205} y={40} className="pv-cap" fill="var(--pv-a)">
        revise
      </text>
    </Frame>
  );
}

