/* 11 — in production */
function ShipIt() {
  const stat = (x, n, l) => (
    <g>
      <text x={x} y={62} className="pv-num pv-sm2">
        {n}
      </text>
      <text x={x} y={80} className="pv-cap">
        {l}
      </text>
    </g>
  );
  const up = [10, 14, 12, 18, 22, 21, 28, 34, 33, 40, 46, 52];
  return (
    <Frame label="A production dashboard with users, latency and cost">
      {stat(28, "1,284", "users")}
      {stat(124, "1.2s", "p95")}
      {stat(212, "$38", "per day")}
      {up.map((h, i) => (
        <rect
          key={i}
          className="pv-bar-v"
          style={{ animationDelay: `${i * 50}ms` }}
          x={28 + i * 22}
          y={170 - h * 1.4}
          width={14}
          height={h * 1.4}
          rx={3}
          fill="var(--pv-a)"
          opacity={0.35 + i * 0.05}
        />
      ))}
    </Frame>
  );
}

const PREVIEWS = {
  "cost-lens": CostLens,
  extractor: Extractor,
  "rag-evals": RagEvals,
  "raw-agent": RawAgent,
  "patterns-kit": PatternsKit,
  "mcp-server": McpServer,
  "coding-harness": CodingHarness,
  "research-team": ResearchTeam,
  "eval-ci": EvalCi,
  "resilient-voice": ResilientVoice,
  "ship-it": ShipIt,
};

export default function ProjectPreview({ id }) {
  const P = PREVIEWS[id];
  return P ? <P /> : null;
}
