import React, { useEffect, useRef, useState } from "react";
import { tracks, pathsOfTrack, pathHours, pathStageCount } from "./learnData";
import "./RouteChooser.css";

/* ============================================================
   🧭 CHOOSE A ROUTE — "What are you here to build?"
   ------------------------------------------------------------
   Three paths as tabs over one panel. Left: who the path is
   for, its size in three numbers, what you finish with, and the
   concrete first step. Right: the route map — every track down
   the side, every path across — where the chosen path's column
   shows the ORDER it walks its tracks in, so the overlap between
   paths is something you see rather than read.
   ============================================================ */

const short = (t) =>
  t.split(" — ")[0].replace("Retrieval-Augmented Generation", "RAG");
const colName = (p) =>
  p.label === "Agentic AI Engineering" ? "Agentic" : p.label;

const doneOf = (stages, progress) =>
  stages.filter((st) => progress[st.id]).length;

export default function RouteChooser({
  paths,
  chosenId,
  progress,
  onChoose,
  onOpenStage,
  foot,
}) {
  const initial = chosenId || (paths.find((p) => p.headline) || paths[0]).id;
  const [at, setAt] = useState(initial);
  const [why, setWhy] = useState(false);
  const [hover, setHover] = useState(null);
  const p = paths.find((x) => x.id === at) || paths[0];

  // A chosen path elsewhere on the page (planner, URL) should show here too.
  useEffect(() => {
    if (chosenId) setAt(chosenId);
  }, [chosenId]);

  const pick = (id) => {
    setAt(id);
    setWhy(false);
  };

  /* Sliding indicator under the active tab — measured, not guessed, so it
     fits labels of any length. */
  const tabsRef = useRef(null);
  const [ind, setInd] = useState(null);
  useEffect(() => {
    const wrap = tabsRef.current;
    const el = wrap && wrap.querySelector(`[data-id="${at}"]`);
    if (!el) return undefined;
    const place = () => setInd({ left: el.offsetLeft, width: el.offsetWidth });
    place();
    window.addEventListener("resize", place);
    return () => window.removeEventListener("resize", place);
  }, [at]);

  const onTabKey = (e) => {
    const i = paths.findIndex((x) => x.id === at);
    let j = null;
    if (e.key === "ArrowRight") j = (i + 1) % paths.length;
    if (e.key === "ArrowLeft") j = (i - 1 + paths.length) % paths.length;
    if (e.key === "Home") j = 0;
    if (e.key === "End") j = paths.length - 1;
    if (j === null) return;
    e.preventDefault();
    pick(paths[j].id);
    const btn = tabsRef.current.querySelector(`[data-id="${paths[j].id}"]`);
    if (btn) btn.focus();
  };

  // Every track any path uses, in page order — the rows of the map.
  const used = new Set(paths.flatMap((x) => x.tracks.map((t) => t.id)));
  const rows = tracks.filter((t) => used.has(t.id));

  const stages = p.tracks.flatMap((t) => t.stages);
  const done = doneOf(stages, progress);
  const total = pathStageCount(p);
  const next = stages.find((st) => !progress[st.id]) || stages[0];
  const nextTrack = p.tracks.find((t) => t.stages.includes(next));
  const sharedN = p.tracks.filter((t) => pathsOfTrack(t.id).length > 1).length;

  return (
    <section className="lrn-choose" id="choose" data-reveal>
      <p className="lrn-eyebrow">01 — Choose a route</p>
      <h2 className="lrn-h2">What are you here to build?</h2>
      <p className="rt-lede">Pick one — you can switch any time.</p>

      <div className="rt-compare" style={{ "--c": p.accent }}>
        <div
          className="rt-tabs"
          role="tablist"
          aria-label="Paths"
          ref={tabsRef}
          onKeyDown={onTabKey}
        >
          {ind && (
            <span
              className="rt-tab-ind"
              aria-hidden="true"
              style={{
                transform: `translateX(${ind.left}px)`,
                width: ind.width,
              }}
            />
          )}
          {paths.map((x) => (
            <button
              key={x.id}
              data-id={x.id}
              type="button"
              role="tab"
              id={`rt-tab-${x.id}`}
              aria-selected={at === x.id}
              aria-controls="rt-panel"
              tabIndex={at === x.id ? 0 : -1}
              className={`rt-tab${at === x.id ? " on" : ""}`}
              style={{ "--c": x.accent }}
              onClick={() => pick(x.id)}
            >
              <span className="rt-tab-l">{x.label}</span>{" "}
              <span className="rt-tab-k">{x.kicker}</span>
            </button>
          ))}
        </div>

        <div
          className="rt-panel"
          id="rt-panel"
          role="tabpanel"
          aria-labelledby={`rt-tab-${p.id}`}
        >
          <div className="rt-panel-text" key={p.id}>
            <p className="rt-kicker">
              {p.kicker}
              {p.headline && <span className="rt-flag">where I live</span>}
            </p>
            <h3 className="rt-panel-t">{p.label}</h3>
            <p className="rt-for">{p.forWhom}</p>

            <dl className="rt-stats">
              <div>
                <dt>hours</dt>
                <dd>{pathHours(p)}</dd>
              </div>
              <div>
                <dt>stages</dt>
                <dd>
                  {done > 0 ? (
                    <>
                      {done}
                      <small>/{total}</small>
                    </>
                  ) : (
                    total
                  )}
                </dd>
              </div>
              <div>
                <dt>tracks</dt>
                <dd>{p.tracks.length}</dd>
              </div>
            </dl>
            {done > 0 && (
              <div className="rt-prog" aria-hidden="true">
                <i style={{ width: `${(done / total) * 100}%` }} />
              </div>
            )}

            <p className="rt-finish">
              <b>You finish with</b>
              {p.finish}
            </p>

            <div className="rt-actions">
              <button
                type="button"
                className="rt-cta"
                onClick={() => onChoose(p.id)}
              >
                {chosenId === p.id
                  ? "Showing below ↓"
                  : done > 0
                  ? "Continue this path →"
                  : `Take the ${colName(p)} path →`}
              </button>
              <button
                type="button"
                className="rt-why"
                aria-expanded={why}
                onClick={() => setWhy((w) => !w)}
              >
                {why ? "Less" : "Why this path"}
              </button>
            </div>
            {why && <p className="rt-blurb">{p.blurb}</p>}

            {next && nextTrack && (
              <a
                className="rt-first"
                href={`/learn/${nextTrack.id}#${next.id}`}
                onClick={(e) => {
                  e.preventDefault();
                  onOpenStage(next.id, nextTrack.id);
                }}
              >
                <span>{done > 0 ? "Next up" : "Start with"}</span>
                <b>{next.title.split(" — ")[0]}</b>
                <em>
                  {next.hours}h · {short(nextTrack.title)}
                </em>
              </a>
            )}
          </div>

          <div
            className="rt-map"
            aria-label="Which tracks each path uses, and in what order"
          >
            <div className="rt-map-head">
              <span className="rt-map-k">The route</span>
              {paths.map((x) => (
                <button
                  key={x.id}
                  type="button"
                  className={x.id === p.id ? "on" : ""}
                  style={{ "--c": x.accent }}
                  onClick={() => pick(x.id)}
                  tabIndex={-1}
                >
                  {colName(x)}
                </button>
              ))}
            </div>

            {rows.map((t) => {
              const step = p.trackIds.indexOf(t.id);
              const inPath = step !== -1;
              const shared = pathsOfTrack(t.id).length > 1;
              const td = doneOf(t.stages, progress);
              return (
                <div
                  key={t.id}
                  className={`rt-map-row${inPath ? " in" : " out"}${
                    hover === t.id ? " hot" : ""
                  }`}
                  style={{ "--t": t.accent }}
                  onMouseEnter={() => setHover(t.id)}
                  onMouseLeave={() => setHover(null)}
                >
                  <span className="rt-map-t">
                    <span className="rt-map-name">
                      {short(t.title)}
                      {shared && <em>shared</em>}
                    </span>
                    {inPath && (
                      <span className="rt-map-sub">
                        {hover === t.id
                          ? t.tagline
                          : `${t.hours}h · ${t.stages.length} stage${
                              t.stages.length === 1 ? "" : "s"
                            }`}
                      </span>
                    )}
                    {inPath && td > 0 && (
                      <span className="rt-map-bar" aria-hidden="true">
                        <i
                          style={{ width: `${(td / t.stages.length) * 100}%` }}
                        />
                      </span>
                    )}
                  </span>
                  {paths.map((x) => {
                    const has = x.trackIds.includes(t.id);
                    const on = x.id === p.id;
                    return (
                      <span
                        key={x.id}
                        className={`rt-map-cell${on ? " on" : ""}`}
                      >
                        {has &&
                          (on ? (
                            <b
                              aria-label={`Step ${step + 1} of the ${
                                x.label
                              } path`}
                            >
                              {step + 1}
                            </b>
                          ) : (
                            <i aria-label={`${x.label} includes ${t.title}`} />
                          ))}
                      </span>
                    );
                  })}
                </div>
              );
            })}

            <p className="rt-map-note">
              {sharedN > 0
                ? `Shares ${sharedN} of its ${p.tracks.length} tracks with the other paths — switching later loses less than you'd think.`
                : "Entirely its own route."}
            </p>
          </div>
        </div>
      </div>

      {foot}
    </section>
  );
}
