import React, { useEffect, useRef, useState } from "react";

/* 3.1 — The agent loop. Step through one turn and watch the context grow.
   This is the diagram I wish someone had shown me before I read a single
   framework's documentation. */

const STEPS = [
  {
    node: "model",
    title: "The model is called",
    detail:
      "System prompt + everything accumulated so far goes in. Nothing is remembered between calls — the context IS the memory.",
  },
  {
    node: "decide",
    title: "It emits a tool call",
    detail:
      "Not an action — a request. Structured JSON matching a schema you wrote. The model cannot do anything; it can only ask.",
  },
  {
    node: "gate",
    title: "Your code decides",
    detail:
      "Validate the arguments. Check permissions. For anything destructive, stop and ask a human. This gate is yours, and it is the only real safety boundary.",
  },
  {
    node: "tool",
    title: "The tool runs",
    detail:
      "Ordinary code. A database query, an HTTP call, a file read. This is the part that actually touches the world.",
  },
  {
    node: "append",
    title: "The result goes back into context",
    detail:
      "And this is the loop. The result becomes part of the next prompt, so the model sees what happened and chooses again.",
  },
];

const NODES = [
  { id: "model", label: "model", x: 12, y: 30 },
  { id: "decide", label: "tool call", x: 38, y: 14 },
  { id: "gate", label: "approval", x: 62, y: 14 },
  { id: "tool", label: "tool runs", x: 86, y: 30 },
  { id: "append", label: "context", x: 50, y: 62 },
];

export default function AgentLoop() {
  const [i, setI] = useState(0);
  const [auto, setAuto] = useState(false);
  const timer = useRef(null);

  useEffect(() => {
    if (!auto) return undefined;
    timer.current = setInterval(
      () => setI((n) => (n + 1) % STEPS.length),
      2200
    );
    return () => clearInterval(timer.current);
  }, [auto]);

  const step = STEPS[i];

  return (
    <div className="viz">
      <svg
        className="loop"
        viewBox="0 0 100 76"
        role="img"
        aria-label="The agent loop"
      >
        <path className="loop-path" d="M12,30 L38,14 L62,14 L86,30 L50,62 Z" />
        {NODES.map((n, idx) => (
          <g
            key={n.id}
            className={`loop-node ${idx === i ? "on" : ""} ${
              idx < i ? "past" : ""
            }`}
          >
            <circle cx={n.x} cy={n.y} r="6" />
            <text x={n.x} y={n.y + 11.5}>
              {n.label}
            </text>
          </g>
        ))}
      </svg>

      <div className="viz-presets">
        {STEPS.map((s, idx) => (
          <button
            key={s.node}
            type="button"
            className={`viz-chip ${idx === i ? "on" : ""}`}
            onClick={() => {
              setAuto(false);
              setI(idx);
            }}
          >
            {idx + 1}
          </button>
        ))}
        <button
          type="button"
          className="viz-chip"
          onClick={() => setAuto((a) => !a)}
        >
          {auto ? "Pause" : "Play"}
        </button>
      </div>

      <p className="viz-note" aria-live="polite">
        <strong>{step.title}.</strong> {step.detail}
      </p>

      <pre className="loop-code">{`while True:
    reply = model(context)          # 1
    if not reply.tool_calls:        #
        return reply                #
    for call in reply.tool_calls:   # 2
        approve(call)               # 3  ← your gate, not the model's
        result = tools[call.name](**call.args)   # 4
        context.append(result)      # 5`}</pre>

      <p className="viz-caveat">
        That is genuinely the whole thing. Every agent framework you will read
        about is a wrapper around these nine lines — which is exactly why you
        should write them yourself once before picking one.
      </p>
    </div>
  );
}
