import React, { useEffect, useRef, useState } from "react";
import { projects } from "./learnGuide";
import { tracks } from "./learnData";
import ProjectPreview from "./ProjectPreviews";
import "./ProjectLadder.css";

/* ============================================================
   🪜 PROJECTS — the build ladder
   ------------------------------------------------------------
   Eleven projects in four levels, each needing the one before.
   Preview-first: every project has a small drawing of what you
   end up with (ProjectPreviews.js), a title and a one-line tag;
   the longer brief, the "done when" and the stages that teach
   it only appear once a project is picked.
   ============================================================ */

function stageRef(id) {
  for (const t of tracks) {
    const st = t.stages.find((x) => x.id === id);
    if (st) return { track: t, stage: st };
  }
  return null;
}

const num = (p) => String(projects.indexOf(p) + 1).padStart(2, "0");

/* "Learn it in" — the stages that teach a project, linked into the route. */
function StageLinks({ p, onOpenStage }) {
  return (
    <div className="pj-stages">
      {p.stages.map((sid) => {
        const hit = stageRef(sid);
        if (!hit) return null;
        return (
          <a
            key={sid}
            href={`/learn/${hit.track.id}#${sid}`}
            className="pj-stage"
            style={{ "--c": hit.track.accent }}
            onClick={(e) => {
              e.preventDefault();
              onOpenStage(sid, hit.track.id);
            }}
          >
            {hit.stage.title.split(" — ")[0]}
          </a>
        );
      })}
      {p.mine && (
        <a href={p.mine.href} className="pj-stage pj-mine">
          {p.mine.label} <span aria-hidden="true">→</span>
        </a>
      )}
    </div>
  );
}

function Thumb({ p, live }) {
  return (
    <span className={`pj-thumb${live ? " is-live" : ""}`}>
      <ProjectPreview id={p.id} />
    </span>
  );
}

/* A 21st-style tile: picture, name, one line of meta. */
function Tile({ p, on, onPick }) {
  const [hover, setHover] = useState(false);
  return (
    <button
      type="button"
      className={`pj-tile${on ? " on" : ""}`}
      aria-pressed={on}
      onClick={() => onPick(p.id)}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      onFocus={() => setHover(true)}
      onBlur={() => setHover(false)}
    >
      <Thumb p={p} live={hover || on} />
      <span className="pj-tile-cap">
        <span className="pj-tile-t">{p.title}</span>
        <span className="pj-tile-m">
          {p.level} · {p.hours}h
        </span>
      </span>
    </button>
  );
}

/* ---------------------------------------------------------------- */
/*  Spotlight: one featured project, then the rail of all of them   */
/* ---------------------------------------------------------------- */
function Spotlight({ onOpenStage }) {
  const [at, setAt] = useState(0);
  const [more, setMore] = useState(false);
  const p = projects[at];
  const next = projects[(at + 1) % projects.length];
  const railRef = useRef(null);

  const go = (i) => {
    setAt((i + projects.length) % projects.length);
    setMore(false);
  };

  // Keep the picked tile in view inside the rail (the rail scrolls, the
  // page doesn't — so this is safe here).
  useEffect(() => {
    const rail = railRef.current;
    const el = rail && rail.children[at];
    if (!rail || !el) return;
    const l = el.offsetLeft - rail.offsetLeft;
    if (
      l < rail.scrollLeft ||
      l + el.offsetWidth > rail.scrollLeft + rail.clientWidth
    )
      rail.scrollTo({ left: l - 12, behavior: "smooth" });
  }, [at]);

  return (
    <>
      <div className="pj-spot">
        <div className="pj-spot-text" key={p.id}>
          <p className="pj-spot-k">
            <span className="pj-level">{p.level}</span>
            <span>
              {num(p)} / {projects.length}
            </span>
          </p>
          <h3 className="pj-spot-t">{p.title}</h3>
          <p className="pj-spot-tag">{p.tag}</p>
          <p className="pj-spot-meta">
            ~{p.hours}h · {p.learn.join(" · ")}
          </p>

          <StageLinks p={p} onOpenStage={onOpenStage} />

          <button
            type="button"
            className="pj-more"
            aria-expanded={more}
            onClick={() => setMore((m) => !m)}
          >
            {more ? "Less" : "What you build"}
          </button>
          {more && (
            <div className="pj-more-body">
              <p>{p.build}</p>
              <p className="pj-done">
                <b>Done when</b> {p.done}
              </p>
            </div>
          )}

          <div className="pj-next">
            <span className="pj-next-t">
              Up next — <b>{next.title}</b>
            </span>
            <span className="pj-next-btns">
              <button
                type="button"
                onClick={() => go(at - 1)}
                aria-label="Previous project"
              >
                ‹
              </button>
              <button type="button" onClick={() => go(at + 1)}>
                Next
              </button>
            </span>
          </div>
        </div>

        <div className="pj-spot-stage" key={`s-${p.id}`}>
          <Thumb p={p} live />
        </div>
      </div>

      <div className="pj-rail-head">
        <span>All projects</span>
        <em>easiest first</em>
      </div>
      <div className="pj-rail" ref={railRef}>
        {projects.map((q, i) => (
          <Tile key={q.id} p={q} on={i === at} onPick={() => go(i)} />
        ))}
      </div>
    </>
  );
}

export default function ProjectLadder({ onOpenStage }) {
  const totalHours = projects.reduce((n, p) => n + p.hours, 0);

  return (
    <section className="lrn-projects" id="projects" data-reveal>
      <div className="lrn-projects-head">
        <div>
          <p className="lrn-eyebrow">04 — Build to learn</p>
          <h2 className="lrn-h2">Projects that make you good at this</h2>
          <p className="pj-lede">
            Eleven builds, easiest first. Each one ends in a number.
          </p>
        </div>
        <p className="lrn-showcase-meta">
          {projects.length} projects · ~{totalHours}h
        </p>
      </div>

      <Spotlight onOpenStage={onOpenStage} />
    </section>
  );
}
