/* ============================================================
   ✅ LEARN — progress, kept in the browser
   ------------------------------------------------------------
   No login, no backend, no gate. Someone landing here from a
   search result should be able to tick things off without ever
   being asked who they are.

   Every accessor is wrapped: Safari private mode throws on
   localStorage rather than returning null, and a learning page
   that white-screens because of a storage quirk is absurd.

   LATER: when signed in, mirror to users/{uid}.learning —
   firestore.rules already allows a user read/write on their own
   document, so no rules change is needed. On conflict local
   wins: it is where they actually clicked.
   ============================================================ */

const KEY = "learn.progress.v1";
const PATH_KEY = "learn.path.v1";

export function readProgress() {
  try {
    const raw = localStorage.getItem(KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

export function writeProgress(map) {
  try {
    localStorage.setItem(KEY, JSON.stringify(map));
  } catch (e) {
    /* private mode, quota, blocked storage — the page still works */
  }
}

export function toggleStage(map, stageId) {
  const next = { ...map };
  if (next[stageId]) delete next[stageId];
  else next[stageId] = true;
  writeProgress(next);
  return next;
}

export function clearProgress() {
  try {
    localStorage.removeItem(KEY);
  } catch (e) {
    /* noop */
  }
  return {};
}

/* Which of the three paths this visitor chose. Remembered so a returning
   reader lands back where they were rather than being asked again — the
   question is only interesting the first time. */
export function readPath() {
  try {
    return localStorage.getItem(PATH_KEY) || null;
  } catch (e) {
    return null;
  }
}

export function writePath(id) {
  try {
    if (id) localStorage.setItem(PATH_KEY, id);
    else localStorage.removeItem(PATH_KEY);
  } catch (e) {
    /* noop */
  }
}
