import React from "react";
import Header from "../../components/header/Header";
import Footer from "../../components/footer/Footer";
import LearnRoadmap from "./LearnRoadmap";

function Learn(props) {
  // /learn/:track only picks the rail highlight and the scroll target — the
  // page always renders every track, top to bottom.
  const activeTrack = props.match?.params?.track || null;

  return (
    <div className="learn-main">
      <Header theme={props.theme} setTheme={props.setTheme} />
      <LearnRoadmap activeTrack={activeTrack} theme={props.theme} />
      <Footer theme={props.theme} />
    </div>
  );
}

export default Learn;
