import React, { useState } from "react";
import { EMBEDDING_WORDS, EMBEDDING_GROUPS } from "../learnViz";

/* 0.2 — Embeddings. Meaning becomes position. Hover a word and its three
   nearest neighbours light up; the distances shown are the real distances
   in the picture you are looking at. */

function nearest(word, n = 3) {
  return EMBEDDING_WORDS.filter((o) => o.w !== word.w)
    .map((o) => ({
      ...o,
      d: Math.hypot(o.x - word.x, o.y - word.y),
    }))
    .sort((a, b) => a.d - b.d)
    .slice(0, n);
}

export default function EmbeddingSpace() {
  const [active, setActive] = useState(null);
  const near = active ? nearest(active) : [];
  const nearNames = near.map((n) => n.w);

  return (
    <div className="viz">
      <svg
        className="emb"
        viewBox="0 0 100 100"
        role="img"
        aria-label="A two-dimensional map of words, clustered by meaning"
      >
        {active &&
          near.map((n) => (
            <line
              key={n.w}
              x1={active.x}
              y1={active.y}
              x2={n.x}
              y2={n.y}
              className="emb-link"
            />
          ))}
        {EMBEDDING_WORDS.map((w) => {
          const isActive = active && active.w === w.w;
          const isNear = nearNames.includes(w.w);
          return (
            <g
              key={w.w}
              className={`emb-node ${isActive ? "on" : ""} ${
                isNear ? "near" : ""
              } ${active && !isActive && !isNear ? "dim" : ""}`}
              onMouseEnter={() => setActive(w)}
              onFocus={() => setActive(w)}
              onMouseLeave={() => setActive(null)}
              onBlur={() => setActive(null)}
              tabIndex={0}
              role="button"
              aria-label={w.w}
            >
              <circle cx={w.x} cy={w.y} r="1.6" fill={EMBEDDING_GROUPS[w.g]} />
              <text x={w.x + 2.6} y={w.y + 1.1} fill={EMBEDDING_GROUPS[w.g]}>
                {w.w}
              </text>
            </g>
          );
        })}
      </svg>

      <p className="viz-note" aria-live="polite">
        {active ? (
          <>
            Closest to <strong>{active.w}</strong>: {nearNames.join(", ")} — and
            not one of them had to share a letter with it.
          </>
        ) : (
          <>
            Hover a word. Nothing here knows what a dog <em>is</em> — it only
            knows that “dog” sits near “puppy” and far from “loan”. That
            distance is what every retrieval system in Track 2 is measuring.
          </>
        )}
      </p>
      <p className="viz-caveat">
        Illustrative layout. Real embeddings live in hundreds of dimensions and
        get squashed to two for pictures like this one — the clusters survive
        the squashing, the precise distances do not.
      </p>
    </div>
  );
}
