import React, { useEffect, useMemo, useRef, useState } from "react";
import { tracks } from "./learnData";
import "./LearnSearch.css";

/* ============================================================
   SEARCH THE ROUTE — press "/"
   ------------------------------------------------------------
   Forty-odd stages and a hundred-odd resources, and the only way
   to find "where does this page talk about MCP" was to pick a
   path, pick a track and read. This indexes stages, tracks and
   resources and jumps straight to the answer.

   "/" rather than ⌘K: the floating assistant already owns ⌘K
   sitewide, and "/" is the other key people try on a docs page.
   ============================================================ */

const TYPE_WORD = {
  video: "Video",
  article: "Article",
  paper: "Paper",
  repo: "Code",
  docs: "Docs",
  course: "Course",
  channel: "Channel",
  service: "Paid",
};

function buildIndex() {
  const out = [];
  tracks.forEach((t) => {
    out.push({
      kind: "track",
      key: `t:${t.id}`,
      title: t.title,
      sub: t.tagline,
      accent: t.accent,
      trackId: t.id,
      hay: [t.title, t.tagline, t.blurb, t.chip].join(" ").toLowerCase(),
    });
    t.stages.forEach((st) => {
      out.push({
        kind: "stage",
        key: `s:${st.id}`,
        title: st.title,
        sub: t.title,
        accent: t.accent,
        trackId: t.id,
        stageId: st.id,
        titleHay: st.title.toLowerCase(),
        hay: [st.title, st.outcome, (st.concepts || []).join(" "), st.note]
          .filter(Boolean)
          .join(" ")
          .toLowerCase(),
      });
      (st.resources || []).forEach((r) => {
        out.push({
          kind: "res",
          key: `r:${st.id}:${r.url}`,
          title: r.title,
          sub: `${TYPE_WORD[r.type] || r.type} · ${r.by}${
            r.cost === "free" ? " · free" : ""
          }`,
          accent: t.accent,
          url: r.url,
          titleHay: r.title.toLowerCase(),
          hay: [r.title, r.by, r.why, r.type].join(" ").toLowerCase(),
        });
      });
    });
  });
  return out;
}

const KIND_RANK = { stage: 0, track: 1, res: 2 };
const KIND_LABEL = { stage: "Stage", track: "Track", res: "Resource" };
const SUGGEST = ["MCP", "RAG", "evals", "attention", "tracing", "agents"];

function search(index, q) {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  const hits = [];
  index.forEach((item) => {
    if (!words.every((w) => item.hay.includes(w))) return;
    let score = KIND_RANK[item.kind] * 2;
    const th = item.titleHay || item.title.toLowerCase();
    if (words.every((w) => th.includes(w))) score -= 3;
    if (th.startsWith(words[0])) score -= 1;
    hits.push({ item, score });
  });
  hits.sort((a, b) => a.score - b.score);
  // A popular term matches thirty resources; cap them so the stages that
  // teach it are not pushed off the list by the reading that supports it.
  const out = [];
  let res = 0;
  for (const h of hits) {
    if (h.item.kind === "res" && ++res > 6) continue;
    out.push(h.item);
    if (out.length >= 12) break;
  }
  return out;
}

/** Wrap each query word in <mark>, case-insensitively. */
function highlight(text, q) {
  const words = q.split(/\s+/).filter(Boolean);
  if (!words.length) return text;
  const esc = words.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const parts = text.split(new RegExp(`(${esc.join("|")})`, "ig"));
  return parts.map((p, i) =>
    i % 2 ? <mark key={i}>{p}</mark> : <React.Fragment key={i}>{p}</React.Fragment>
  );
}

function isTyping(el) {
  if (!el) return false;
  const tag = el.tagName;
  return (
    tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || el.isContentEditable
  );
}

export default function LearnSearch({ open, setOpen, onStage, onTrack }) {
  const index = useMemo(buildIndex, []);
  const [q, setQ] = useState("");
  const [sel, setSel] = useState(0);
  const input = useRef(null);
  const list = useRef(null);
  const results = useMemo(() => search(index, q), [index, q]);

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === "/" && !open && !isTyping(document.activeElement)) {
        e.preventDefault();
        setOpen(true);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, setOpen]);

  useEffect(() => {
    if (!open) return undefined;
    setSel(0);
    const t = setTimeout(() => input.current && input.current.focus(), 20);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => {
      clearTimeout(t);
      document.body.style.overflow = prev;
    };
  }, [open]);

  useEffect(() => setSel(0), [q]);

  useEffect(() => {
    const el = list.current && list.current.querySelector('[aria-selected="true"]');
    if (el && el.scrollIntoView) el.scrollIntoView({ block: "nearest" });
  }, [sel]);

  if (!open) return null;

  const close = () => {
    setOpen(false);
    setQ("");
  };

  const go = (item) => {
    if (!item) return;
    close();
    if (item.kind === "res") window.open(item.url, "_blank", "noopener");
    else if (item.kind === "stage") onStage(item.stageId, item.trackId);
    else onTrack(item.trackId);
  };

  const onKeyDown = (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      close();
    } else if (e.key === "ArrowDown") {
      e.preventDefault();
      setSel((s) => Math.min(s + 1, results.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setSel((s) => Math.max(s - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      go(results[sel]);
    }
  };

  return (
    <div className="lsr" role="presentation" onMouseDown={close}>
      <div
        className="lsr-panel"
        role="dialog"
        aria-modal="true"
        aria-label="Search the route"
        onMouseDown={(e) => e.stopPropagation()}
        onKeyDown={onKeyDown}
      >
        <div className="lsr-field">
          <svg viewBox="0 0 20 20" aria-hidden="true">
            <circle cx="9" cy="9" r="6" />
            <path d="M13.5 13.5 18 18" />
          </svg>
          <input
            ref={input}
            value={q}
            onChange={(e) => setQ(e.target.value)}
            placeholder="Search stages, tracks and resources…"
            aria-label="Search"
            aria-controls="lsr-results"
            aria-activedescendant={
              results[sel] ? `lsr-${results[sel].key}` : undefined
            }
            role="combobox"
            aria-expanded={results.length > 0}
            spellCheck="false"
            autoComplete="off"
          />
          <kbd onClick={close}>esc</kbd>
        </div>

        {q.trim() === "" ? (
          <div className="lsr-empty">
            <span>Try</span>
            {SUGGEST.map((s) => (
              <button key={s} type="button" onClick={() => setQ(s)}>
                {s}
              </button>
            ))}
          </div>
        ) : results.length === 0 ? (
          <p className="lsr-none">
            Nothing on the route mentions “{q}”. That's either a gap or a
            buzzword — <a href="/contact">tell me which</a>.
          </p>
        ) : (
          <ul className="lsr-list" id="lsr-results" role="listbox" ref={list}>
            {results.map((item, i) => (
              <li
                key={item.key}
                id={`lsr-${item.key}`}
                role="option"
                aria-selected={i === sel}
                className={`lsr-item${i === sel ? " on" : ""}`}
                style={{ "--c": item.accent }}
                onMouseMove={() => setSel(i)}
                onClick={() => go(item)}
              >
                <span className="lsr-kind">{KIND_LABEL[item.kind]}</span>
                <span className="lsr-main">
                  <span className="lsr-title">{highlight(item.title, q)}</span>
                  <span className="lsr-sub">{item.sub}</span>
                </span>
                <span className="lsr-go" aria-hidden="true">
                  {item.kind === "res" ? "↗" : "↵"}
                </span>
              </li>
            ))}
          </ul>
        )}

        <p className="lsr-foot">
          <span>
            <kbd>↑</kbd>
            <kbd>↓</kbd> move
          </span>
          <span>
            <kbd>↵</kbd> open
          </span>
          <span>
            <kbd>/</kbd> anywhere on this page
          </span>
        </p>
      </div>
    </div>
  );
}
